plan.diagrama:
capas:
  - { id: cli, nombre: CLI }
  - { id: repo, nombre: Repo }
participantes:
  - { id: Op, nombre: "operador", capa: cli, hace: "Corre scripts/ruta directo 0028", vive_en: ["scripts/ruta"] }
  - { id: Im, nombre: "implementador", capa: repo, hace: "Implementa la spec 0028 dentro de su alcance", vive_en: [".claude/agents/implementador.md"] }
  - { id: Ve, nombre: "verificador", capa: repo, hace: "Corre scripts/verify y devuelve el desglose por CA", vive_en: [".claude/agents/verificador.md"] }
secuencia:
  - { de: Op, a: Im, msg: "Implementa la spec 0028", tipo: peticion, activa: true }
  - { de: Im, a: Ve, msg: "listo para verificar", tipo: peticion }
  - { de: Ve, a: Op, msg: "desglose por CA", tipo: respuesta }
  - alt: "todos los CA en PASS"
    pasos:
      - { de: Ve, a: Op, msg: "pasa: true", tipo: respuesta }
    else: "algun CA en FAIL"
    pasos_else:
      - { de: Ve, a: Op, msg: "segunda vuelta", tipo: respuesta }
